// Merge with existing states (replacing or augmenting)
const finalMergedHierarchy = [];
const existingMap = {};
existingData.forEach(s => {
  existingMap[s.name] = s;
});

// Take the full set of 29 states
const all29StateNames = [
  'Andhra Pradesh', 'Telangana', 'Maharashtra', 'Karnataka', 'Tamil Nadu',
  'Delhi NCR (UT)', 'Kerala', 'Gujarat', 'Rajasthan', 'Uttar Pradesh',
  'West Bengal', 'Madhya Pradesh', 'Punjab', 'Haryana', 'Bihar',
  'Odisha', 'Jharkhand', 'Chhattisgarh', 'Assam', 'Uttarakhand',
  'Himachal Pradesh', 'Goa', 'Tripura', 'Meghalaya', 'Manipur',
  'Nagaland', 'Mizoram', 'Arunachal Pradesh', 'Sikkim'
];

all29StateNames.forEach(stName => {
  const addState = additionalStates.find(s => s.name === stName);
  const exState = existingMap[stName];
  if (addState) {
    finalMergedHierarchy.push(addState);
  } else if (exState) {
    finalMergedHierarchy.push(exState);
  }
});

const outputPath = path.join(__dirname, 'statesData.js');
fs.writeFileSync(outputPath, `// COMPLETE OFFICIAL ALL-INDIA HIERARCHY FOR ALL 29 STATES & UTs
// Mapped with authentic Districts, Cities, Mandals/Taluks/Areas, Hospitals & Exterior Photos

module.exports = ${JSON.stringify(finalMergedHierarchy, null, 2)};\n`, 'utf-8');

